const typeIn = async (sel, value) => { const root = container.querySelector(sel); const inner = root.querySelector('input') || root; inner.value = value; inner.dispatchEvent(new Event('input', { bubbles: true })); await tick(); };
await typeIn('[data-test="name"]', 'Phoenix');
container.querySelector('[data-test="next"]').click();
await tick();
await typeIn('[data-test="role"]', 'researcher');
container.querySelector('[data-test="next"]').click();
await tick();
const summary = container.querySelector('[data-test="summary"]');
expect(summary, 'summary tile present');
expect(summary.textContent.includes('Phoenix') && summary.textContent.includes('researcher'), 'summary text: ' + summary.textContent);
container.querySelector('[data-test="submit"]').click();
await tick();
await tick();
await tick();
const done = container.querySelector('[data-test="done"]');
expect(done, 'done message rendered after submit');
expect(/Created agent u\d+/.test(done.textContent), 'done text: ' + done.textContent);
